<style>
.ticket-sheet{box-sizing:border-box;width:194mm;height:280mm;display:grid;grid-template-columns:repeat(var(--sheet-columns),minmax(0,1fr));grid-template-rows:repeat(var(--sheet-rows),minmax(0,1fr));gap:3mm;background:#fff;color:#1e293b;font-family:Arial,Helvetica,sans-serif;--bt-font:2.2mm;--bt-cell:4.2mm;--bt-heading:3.6mm;--bt-header-pad:2.4mm;--bt-body-pad:2mm;--bt-icon:3.6mm}.ticket-sheet *{box-sizing:border-box}.blank-ticket{min-width:0;min-height:0;border:.35mm solid color-mix(in srgb,var(--ticket-accent),white 65%);border-radius:3mm;display:flex;flex-direction:column;overflow:hidden;font-size:var(--bt-font);line-height:1.2;background:linear-gradient(135deg,#fff,var(--ticket-tint));position:relative;overflow-wrap:anywhere}.bt-icon{width:var(--bt-icon);height:var(--bt-icon);flex-shrink:0;color:var(--ticket-accent)}.bt-header{position:relative;isolation:isolate;overflow:hidden;display:flex;align-items:center;gap:2mm;padding:var(--bt-header-pad);color:#fff;background:linear-gradient(115deg,color-mix(in srgb,var(--ticket-accent),#001e37 45%),var(--ticket-accent));min-height:13mm;flex-shrink:0}.bt-header:before,.bt-header:after{content:"";position:absolute;z-index:-1;pointer-events:none;background:#ffffff0d;transform:rotate(-30deg);border-radius:40%;width:42mm;height:32mm;right:12%;top:-22mm}.bt-header:after{width:28mm;height:23mm;right:-6mm;top:3mm;background:#ffffff10;transform:rotate(25deg)}.bt-heading{min-width:0;flex:1}.bt-header h2{font-size:var(--bt-heading);line-height:1.08;letter-spacing:.05mm;text-transform:uppercase;margin:0;font-weight:800;overflow-wrap:anywhere}.bt-title{font-size:calc(var(--bt-font) * 1.06);font-weight:800;letter-spacing:.65mm;color:var(--ticket-light);margin-top:1mm}.bt-eyebrow{display:none}.bt-emblem{display:flex;align-items:center;justify-content:center;width:10mm;height:10mm;flex-shrink:0;border-radius:50%;background:#ffffffed;color:var(--ticket-accent)}.bt-emblem .bt-icon{width:6mm;height:6mm;color:inherit;stroke-width:1.8}.bt-mo